            // We have passed a color index and are now going through color spec.
        } else if (parsingPairStart < 0 && (b >= '0' && b <= '9')) {
            colorIndex = ((colorIndex < 0) ? 0 : colorIndex * 10) + (b - '0');
        } else {
            unknownSequence(b);
            return;
        }
        if (endOfInput) break;
    }
    break;

