1231	    public void doDecSetOrReset(boolean setting, int externalBit) {
1232	        int internalBit = mapDecSetBitToInternalBit(externalBit);
1233	        if (internalBit != -1) {
1234	            setDecsetinternalBit(internalBit, setting);
1235	        }
1236	        switch (externalBit) {
1237	            case 1: // Application Cursor Keys (DECCKM).
1238	                break;
1239	            case 3: // Set: 132 column mode (. Reset: 80 column mode. ANSI name: DECCOLM.
1240	                // We don't actually set/reset 132 cols, but we do want the side effects
1241	                // (FIXME: Should only do this if the 95 DECSET bit (DECNCSM) is set, and if changing value?):
1242	                // Sets the left, right, top and bottom scrolling margins to their default positions, which is important for
1243	                // the "reset" utility to really reset the terminal:
1244	                mLeftMargin = mTopMargin = 0;
1245	                mBottomMargin = mRows;
1246	                mRightMargin = mColumns;
1247	                // "DECCOLM resets vertical split screen mode (DECLRMM) to unavailable":
1248	                setDecsetinternalBit(DECSET_BIT_LEFTRIGHT_MARGIN_MODE, false);
1249	                // "Erases all data in page memory":
1250	                blockClear(0, 0, mColumns, mRows);
1251	                setCursorRowCol(0, 0);
1252	                break;
1253	            case 4: // DECSCLM-Scrolling Mode. Ignore.
1254	                break;
1255	            case 5: // Reverse video. No action.
1256	                break;
