1331	    private void doCsiBiggerThan(int b) {
1332	        switch (b) {
1333	            case 'c': // "${CSI}>c" or "${CSI}>c". Secondary Device Attributes (DA2).
1334	                // Originally this was used for the terminal to respond with "identification code, firmware version level,
1335	                // and hardware options" (http://vt100.net/docs/vt510-rm/DA2), with the first "41" meaning the VT420
1336	                // terminal type. This is not used anymore, but the second version level field has been changed by xterm
1337	                // to mean it's release number ("patch numbers" listed at http://invisible-island.net/xterm/xterm.log.html),
1338	                // and some applications use it as a feature check:
1339	                // * tmux used to have a "xterm won't reach version 500 for a while so set that as the upper limit" check,
1340	                // and then check "xterm_version > 270" if rectangular area operations such as DECCRA could be used.
1341	                // * vim checks xterm version number >140 for "Request termcap/terminfo string" functionality >276 for SGR
1342	                // mouse report.
