505	    private void processByte(byte byteToProcess) {
506	        if (mUtf8ToFollow > 0) {
507	            if ((byteToProcess & 0b11000000) == 0b10000000) {
508	                // 10xxxxxx, a continuation byte.
509	                mUtf8InputBuffer[mUtf8Index++] = byteToProcess;
510	                if (--mUtf8ToFollow == 0) {
511	                    byte firstByteMask = (byte) (mUtf8Index == 2 ? 0b00011111 : (mUtf8Index == 3 ? 0b00001111 : 0b00000111));
512	                    int codePoint = (mUtf8InputBuffer[0] & firstByteMask);
513	                    for (int i = 1; i < mUtf8Index; i++)
514	                        codePoint = ((codePoint << 6) | (mUtf8InputBuffer[i] & 0b00111111));
515	                    if (((codePoint <= 0b1111111) && mUtf8Index > 1) || (codePoint < 0b11111111111 && mUtf8Index > 2)
516	                        || (codePoint < 0b1111111111111111 && mUtf8Index > 3)) {
517	                        // Overlong encoding.
518	                        codePoint = UNICODE_REPLACEMENT_CHAR;
519	                    }
520	
521	                    mUtf8Index = mUtf8ToFollow = 0;
522	
523	                    if (codePoint >= 0x80 && codePoint <= 0x9F) {
524	                        // Sequence decoded to a C1 control character which we ignore. They are
525	                        // not used nowadays and increases the risk of messing up the terminal state
526	                        // on binary input. XTerm does not allow them in utf-8:
527	                        // "It is not possible to use a C1 control obtained from decoding the
528	                        // UTF-8 text" - http://invisible-island.net/xterm/ctlseqs/ctlseqs.html
529	                    } else {
530	                        switch (Character.getType(codePoint)) {
531	                            case Character.UNASSIGNED:
532	                            case Character.SURROGATE:
533	                                codePoint = UNICODE_REPLACEMENT_CHAR;
534	                        }
535	                        processCodePoint(codePoint);
536	                    }
537	                }
538	            } else {
539	                // Not a UTF-8 continuation byte so replace the entire sequence up to now with the replacement char:
540	                mUtf8Index = mUtf8ToFollow = 0;
541	                emitCodePoint(UNICODE_REPLACEMENT_CHAR);
542	                // The Unicode Standard Version 6.2 – Core Specification
543	                // (http://www.unicode.org/versions/Unicode6.2.0/ch03.pdf):
544	                // "If the converter encounters an ill-formed UTF-8 code unit sequence which starts with a valid first
545	                // byte, but which does not continue with valid successor bytes (see Table 3-7), it must not consume the
546	                // successor bytes as part of the ill-formed subsequence
547	                // whenever those successor bytes themselves constitute part of a well-formed UTF-8 code unit
548	                // subsequence."
549	                processByte(byteToProcess);
550	            }
551	        } else {
552	            if ((byteToProcess & 0b10000000) == 0) { // The leading bit is not set so it is a 7-bit ASCII character.
553	                processCodePoint(byteToProcess);
554	                return;
555	            } else if ((byteToProcess & 0b11100000) == 0b11000000) { // 110xxxxx, a two-byte sequence.
556	                mUtf8ToFollow = 1;
557	            } else if ((byteToProcess & 0b11110000) == 0b11100000) { // 1110xxxx, a three-byte sequence.
558	                mUtf8ToFollow = 2;
559	            } else if ((byteToProcess & 0b11111000) == 0b11110000) { // 11110xxx, a four-byte sequence.
560	                mUtf8ToFollow = 3;
561	            } else {
562	                // Not a valid UTF-8 sequence start, signal invalid data:
563	                processCodePoint(UNICODE_REPLACEMENT_CHAR);
