570	    public void processCodePoint(int b) {
571	        // The Application Program-Control (APC) string might be arbitrary non-printable characters, so handle that early.
572	        if (mEscapeState == ESC_APC) {
573	            doApc(b);
574	            return;
575	        } else if (mEscapeState == ESC_APC_ESCAPE) {
576	            doApcEscape(b);
577	            return;
578	        }
579	
580	        switch (b) {
581	            case 0: // Null character (NUL, ^@). Do nothing.
582	                break;
583	            case 7: // Bell (BEL, ^G, \a). If in an OSC sequence, BEL may terminate a string; otherwise signal bell.
584	                if (mEscapeState == ESC_OSC)
585	                    doOsc(b);
586	                else
587	                    mSession.onBell();
588	                break;
589	            case 8: // Backspace (BS, ^H).
590	                if (mLeftMargin == mCursorCol) {
591	                    // Jump to previous line if it was auto-wrapped.
592	                    int previousRow = mCursorRow - 1;
593	                    if (previousRow >= 0 && mScreen.getLineWrap(previousRow)) {
594	                        mScreen.clearLineWrap(previousRow);
595	                        setCursorRowCol(previousRow, mRightMargin - 1);
596	                    }
597	                } else {
598	                    setCursorCol(mCursorCol - 1);
599	                }
600	                break;
601	            case 9: // Horizontal tab (HT, \t) - move to next tab stop, but not past edge of screen
602	                // XXX: Should perhaps use color if writing to new cells. Try with
603	                //       printf "\033[41m\tXX\033[0m\n"
604	                // The OSX Terminal.app colors the spaces from the tab red, but xterm does not.
605	                // Note that Terminal.app only colors on new cells, in e.g.
606	                //       printf "\033[41m\t\r\033[42m\tXX\033[0m\n"
607	                // the first cells are created with a red background, but when tabbing over
608	                // them again with a green background they are not overwritten.
609	                mCursorCol = nextTabStop(1);
610	                break;
611	            case 10: // Line feed (LF, \n).
612	            case 11: // Vertical tab (VT, \v).
613	            case 12: // Form feed (FF, \f).
614	                doLinefeed();
615	                break;
616	            case 13: // Carriage return (CR, \r).
617	                setCursorCol(mLeftMargin);
618	                break;
619	            case 14: // Shift Out (Ctrl-N, SO) → Switch to Alternate Character Set. This invokes the G1 character set.
620	                mUseLineDrawingUsesG0 = false;
621	                break;
622	            case 15: // Shift In (Ctrl-O, SI) → Switch to Standard Character Set. This invokes the G0 character set.
623	                mUseLineDrawingUsesG0 = true;
624	                break;
625	            case 24: // CAN.
626	            case 26: // SUB.
627	                if (mEscapeState != ESC_NONE) {
628	                    // FIXME: What is this??
629	                    mEscapeState = ESC_NONE;
630	                    emitCodePoint(127);
631	                }
632	                break;
633	            case 27: // ESC
634	                // Starts an escape sequence unless we're parsing a string
635	                if (mEscapeState == ESC_P) {
636	                    // XXX: Ignore escape when reading device control sequence, since it may be part of string terminator.
637	                    return;
638	                } else if (mEscapeState != ESC_OSC) {
639	                    startEscapeSequence();
640	                } else {
641	                    doOsc(b);
642	                }
643	                break;
644	            default:
645	                mContinueSequence = false;
646	                switch (mEscapeState) {
647	                    case ESC_NONE:
648	                        if (b >= 32) emitCodePoint(b);
649	                        break;
650	                    case ESC:
651	                        doEsc(b);
652	                        break;
653	                    case ESC_POUND:
654	                        doEscPound(b);
655	                        break;
656	                    case ESC_SELECT_LEFT_PAREN: // Designate G0 Character Set (ISO 2022, VT100).
657	                        mUseLineDrawingG0 = (b == '0');
658	                        break;
659	                    case ESC_SELECT_RIGHT_PAREN: // Designate G1 Character Set (ISO 2022, VT100).
660	                        mUseLineDrawingG1 = (b == '0');
661	                        break;
662	                    case ESC_CSI:
663	                        doCsi(b);
664	                        break;
665	                    case ESC_CSI_UNSUPPORTED_PARAMETER_BYTE:
666	                    case ESC_CSI_UNSUPPORTED_INTERMEDIATE_BYTE:
667	                        doCsiUnsupportedParameterOrIntermediateByte(b);
668	                        break;
669	                    case ESC_CSI_EXCLAMATION:
670	                        if (b == 'p') { // Soft terminal reset (DECSTR, http://vt100.net/docs/vt510-rm/DECSTR).
671	                            reset();
672	                        } else {
673	                            unknownSequence(b);
674	                        }
675	                        break;
676	                    case ESC_CSI_QUESTIONMARK:
677	                        doCsiQuestionMark(b);
678	                        break;
679	                    case ESC_CSI_BIGGERTHAN:
680	                        doCsiBiggerThan(b);
681	                        break;
682	                    case ESC_CSI_DOLLAR:
683	                        doCsiDollar(b);
684	                        break;
685	                    case ESC_CSI_DOUBLE_QUOTE:
686	                        doCsiDoubleQuote(b);
687	                        break;
688	                    case ESC_CSI_SINGLE_QUOTE:
